<script setup lang="ts">
import { computed, ref } from 'vue'

interface Props {
  userName: string
  src: string
  alt?: string
  sizeInRem?: number
  backgroundColor?: string
  textColor?: string
  borderRadius?: string
}

const props = withDefaults(defineProps<Props>(), {
  sizeInRem: 2.75,
  backgroundColor: '#dddddd',
  textColor: '#000000',
  borderRadius: '50%',
})

const imageIsDisabled = ref(false)

const size = computed(() => `${props.sizeInRem}rem`)
const nameInitials = computed(() => props.userName.split(' ').slice(0, 2).map(it => it.length > 0 ? it[0] : '').join('').toLocaleUpperCase())

function handleImageLoadError() {
  imageIsDisabled.value = true
}
</script>

<template>
  <template v-if="src && !imageIsDisabled">
    <img
      :src="src" :alt="alt"
      loading="lazy"
      class="flex-shrink-0 object-contain overflow-hidden"
      :style="{
        width: size,
        height: size,
        borderRadius,
      }"
      @error="handleImageLoadError"
    >
  </template>
  <template v-else-if="userName">
    <svg
      xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"
      class="flex-shrink-0"
      :style="{
        width: size,
        height: size,
        backgroundColor,
        borderRadius,
      }"
    >
      <foreignObject width="100" height="100" x="0" y="0">
        <div class="h-full p-[8px] flex justify-center items-center">
          <p class="text-[42px] text-center" :style="{ color: textColor }">
            {{ nameInitials }}
          </p>
        </div>
      </foreignObject>
    </svg>
  </template>
  <template v-else>
    <div
      class="flex-shrink-0"
      :style="{
        width: size,
        height: size,
        backgroundColor,
        borderRadius,
      }"
    />
  </template>
</template>
